import GenProgress from './GenProgress.jsx';
import React, { useEffect, useRef, useState } from 'react';
import { generateFlux3, describeImage, cancelJob } from '../api.js';

// Soul-ID-style consistency without training: one photo -> a character sheet of
// extra views, all generated by Flux 3 reference editing. Every scene still that
// casts this character gets the photo AND up to two sheet views as references.

const BASE = (view) =>
  `Show the exact same person from image 1, ${view}, on a plain neutral light-grey studio background with soft even lighting. Keep the face, hair, skin tone, age and clothing identical to image 1.`;

export const SHEETS = {
  turnaround: {
    label: 'Turnaround (5 views)', size: [832, 1088],
    views: [
      ['3/4 left', 'in a three-quarter view turned slightly to the left, neutral expression'],
      ['Left profile', 'in a left side profile view, neutral expression'],
      ['3/4 right', 'in a three-quarter view turned slightly to the right, neutral expression'],
      ['Right profile', 'in a right side profile view, neutral expression'],
      ['Back', 'seen from directly behind'],
    ],
  },
  fullbody: {
    label: 'Full body (2 views)', size: [768, 1152],
    views: [
      ['Full body front', 'as a full-body shot standing relaxed, head to toe, facing the camera'],
      ['Full body 3/4', 'as a full-body shot standing, turned in a three-quarter view, head to toe'],
    ],
  },
  expressions: {
    label: 'Expressions (6)', size: [1024, 1024],
    views: [
      ['Smile', 'in a close-up portrait with a warm natural smile'],
      ['Laugh', 'in a close-up portrait laughing joyfully'],
      ['Serious', 'in a close-up portrait with a serious intense expression'],
      ['Angry', 'in a close-up portrait looking angry'],
      ['Surprised', 'in a close-up portrait looking genuinely surprised'],
      ['Sad', 'in a close-up portrait looking sad, eyes slightly teary'],
    ],
  },
};

export default function CharacterStudio({ assets, addAsset, updateAssetMeta, onResult, onDelete, onNewScene }) {
  const characters = assets.filter((a) => a.kind === 'character');
  const [confirmDel, setConfirmDel] = useState(null);
  const [selId, setSelId] = useState(null);
  const [sheetKey, setSheetKey] = useState('turnaround');
  const [newPrompt, setNewPrompt] = useState('');
  const [run, setRun] = useState({ phase: 'idle', i: 0, n: 0, status: '', jobId: null, error: null, progress: 0 });
  const [describing, setDescribing] = useState(false);
  const fileRef = useRef(null);
  const cancelled = useRef(false);

  const sel = characters.find((c) => c.id === selId) || null;
  const busy = run.phase === 'run';
  const views = (sel?.meta?.refIds || []).map((id) => assets.find((a) => a.id === id)).filter(Boolean);

  const onEvent = (ev) => {
    if (ev.type === 'submitted') setRun((r) => ({ ...r, jobId: ev.jobId }));
    else if (ev.type === 'progress') setRun((r) => ({ ...r, progress: ev.max ? ev.value / ev.max : 0, status: `Sampling ${ev.value}/${ev.max}` }));
    else if (ev.type === 'status') setRun((r) => ({ ...r, status: ev.text }));
  };

  const upload = (files) => {
    let last = null;
    [...files].forEach((f) => {
      const stem = f.name.replace(/\.[^.]+$/, '').replace(/[_-]+/g, ' ').trim();
      last = addAsset(f, 'character', stem || 'character', { name: /[a-z]{2}/i.test(stem) ? stem.slice(0, 40) : '', description: '', refIds: [] });
    });
    if (last) setSelId(last.id);
  };

  const createFromPrompt = async () => {
    cancelled.current = false;
    setRun({ phase: 'run', i: 0, n: 1, status: 'Submitting…', jobId: null, error: null, progress: 0 });
    try {
      const prompt = `Studio portrait photograph of ${newPrompt.trim()}, head and shoulders, facing the camera with a neutral expression, plain light-grey background, soft even lighting, sharp focus, natural skin texture.`;
      const res = await generateFlux3({ prompt, width: 832, height: 1088, steps: 8, cfg: 1, upsample: false }, [], [], [], onEvent);
      const blob = await (await fetch(res.url)).blob();
      const asset = addAsset(blob, 'character', newPrompt.slice(0, 30), { name: newPrompt.split(/[,.]/)[0].slice(0, 30), description: newPrompt, refIds: [], source: 'flux3' });
      setSelId(asset.id); setNewPrompt('');
      setRun((r) => ({ ...r, phase: 'idle' }));
    } catch (e) { setRun((r) => ({ ...r, phase: e.message === 'Cancelled' ? 'idle' : 'error', error: e.message })); }
  };

  const makeSheet = async () => {
    if (!sel) return;
    cancelled.current = false;
    const sheet = SHEETS[sheetKey];
    setRun({ phase: 'run', i: 0, n: sheet.views.length, status: 'Submitting…', jobId: null, error: null, progress: 0 });
    const newIds = [];
    try {
      for (let i = 0; i < sheet.views.length; i++) {
        if (cancelled.current) break;
        const [label, view] = sheet.views[i];
        const res = await generateFlux3(
          { prompt: BASE(view), width: sheet.size[0], height: sheet.size[1], steps: 8, cfg: 1 },
          [sel.blob], [], [], onEvent,
        );
        const blob = await (await fetch(res.url)).blob();
        const a = addAsset(blob, 'image', `${sel.meta?.name || sel.name} · ${label}`, { characterId: sel.id, view: label, source: 'flux3' });
        newIds.push(a.id);
        updateAssetMeta(sel.id, { refIds: [...(sel.meta?.refIds || []), ...newIds] });
        setRun((r) => ({ ...r, i: i + 1, progress: 0 }));
      }
      setRun((r) => ({ ...r, phase: 'idle', status: 'Done' }));
    } catch (e) {
      updateAssetMeta(sel.id, { refIds: [...(sel.meta?.refIds || []), ...newIds] });
      setRun((r) => ({ ...r, phase: e.message === 'Cancelled' ? 'idle' : 'error', error: e.message }));
    }
  };

  const describe = async () => {
    if (!sel) return;
    setDescribing(true);
    try {
      const r = await describeImage(sel.blob, 'vision');
      updateAssetMeta(sel.id, { description: r.prompt });
    } catch (e) { setRun((x) => ({ ...x, error: `Describe failed: ${e.message}`, phase: 'error' })); } finally { setDescribing(false); }
  };

  const removeView = (id) => updateAssetMeta(sel.id, { refIds: (sel.meta?.refIds || []).filter((x) => x !== id) });

  const [genOpen, setGenOpen] = useState(false);
  useEffect(() => { if (!sel && characters.length) setSelId(characters[0].id); }, [sel, characters]);
  return (
    <div className="edit-studio char-studio cs2">
      <div className="cs-main">
        <div className="cs-cast">
          {characters.map((c) => (
            <button key={c.id} className={`cs-pill ${c.id === selId ? 'on' : ''}`} onClick={() => setSelId(c.id)}>
              <img src={c.url} alt="" />
              <span>{c.meta?.name || c.name}</span>
              <small>{(c.meta?.refIds || []).length} views</small>
            </button>
          ))}
          <span className="spacer" />
          <button onClick={() => fileRef.current?.click()}>＋ Upload photo(s)</button>
          <button className={genOpen ? 'active' : ''} onClick={() => setGenOpen((v) => !v)}>✨ New cast</button>
          <input ref={fileRef} type="file" accept="image/*" multiple hidden
            onChange={(e) => { if (e.target.files?.length) upload(e.target.files); e.target.value = ''; }} />
        </div>
        {genOpen && (
          <div className="cs-gen">
            <textarea rows={2} value={newPrompt} disabled={busy} placeholder="a 30-year-old woman with short red hair and freckles, green eyes"
              onChange={(e) => setNewPrompt(e.target.value)} />
            <button className="primary" disabled={busy || !newPrompt.trim()} onClick={createFromPrompt}>✨ Create character</button>
          </div>
        )}
        {!characters.length && !genOpen && <div className="cs-empty"><b>No characters yet</b><span>Upload a photo, or describe someone and generate them. The same person then stays the same in every scene.</span></div>}

        {sel && (
          <>
            <div className="cs-sechead"><h4>Character sheet</h4><span>{views.length} view{views.length === 1 ? '' : 's'}</span></div>
            <div className="hint">Extra views of the same person. Scenes that cast this character send the photo plus up to 2 views to Flux 3 as references, which locks identity far better than one photo. Use <b>🎬 New scene with this character</b> (inspector, bottom), or open any scene on the Board and pick the name under Cast. Ads (Presenter), Music Video and TikTok Video use your characters too.</div>
            {busy && <GenProgress progress={run.progress} status={run.status} />}
            {run.error && <div className="error">{run.error}</div>}
            <div className="cs-cards">
              <figure className="cs-card anchor"><img src={sel.url} alt="" /><figcaption><b>Primary</b><span>identity anchor</span></figcaption></figure>
              {views.map((v) => (
                <figure key={v.id} className="cs-card">
                  <img src={v.url} alt={v.name} />
                  <figcaption><b>{v.meta?.view}</b><button title="Remove from sheet" onClick={() => removeView(v.id)}>✕</button></figcaption>
                </figure>
              ))}
            </div>
          </>
        )}
      </div>

      <aside className="cs-insp">
        <h3>Character inspector{sel && <small>{(sel.meta?.refIds || []).length} views</small>}</h3>
        {!sel ? <div className="hint" style={{ padding: 18 }}>Pick or create a character to edit its identity.</div> : (
          <>
            <div className="cs-insp-body">
              <div className="cs-anchor"><img src={sel.url} alt="" />
                <div><label>Name<input value={sel.meta?.name || ''} onChange={(e) => updateAssetMeta(sel.id, { name: e.target.value })} /></label></div>
              </div>
              <label>Appearance <span className="param-hint">Added to prompts so wardrobe and hair stay consistent.</span>
                <textarea rows={5} value={sel.meta?.description || ''} onChange={(e) => updateAssetMeta(sel.id, { description: e.target.value })} />
              </label>
              <button disabled={describing || busy} onClick={describe}>{describing ? '⏳' : '👁'} Describe from photo</button>
              <label>Sheet type
                <select value={sheetKey} disabled={busy} onChange={(e) => setSheetKey(e.target.value)}>
                  {Object.entries(SHEETS).map(([k, sh]) => <option key={k} value={k}>{sh.label}</option>)}
                </select>
              </label>
            </div>
            <div className="cs-insp-foot">
              <button className="primary" disabled={busy} onClick={makeSheet}>{busy ? `Generating ${run.i + 1}/${run.n}…` : '🧬 Generate sheet'}</button>
              {busy && <button className="cancel-btn" onClick={() => { cancelled.current = true; if (run.jobId) cancelJob(run.jobId); }}>✕ Stop</button>}
              {onNewScene && !busy && <button title="Start a scene on the Board with this character already cast" onClick={() => onNewScene(sel.id)}>🎬 New scene with this character</button>}
              {onDelete && !busy && (confirmDel === sel.id
                ? <button className="cancel-btn" onClick={() => { onDelete(sel.id); setConfirmDel(null); setSelId(null); }} onBlur={() => setConfirmDel(null)} autoFocus>Really remove "{sel.meta?.name || sel.name}"?</button>
                : <button title="Remove this character and its photo from the project (the sheet views stay in your gallery)" onClick={() => setConfirmDel(sel.id)}>🗑 Remove character</button>)}
            </div>
          </>
        )}
      </aside>
    </div>
  );
}
